urlset:
{%- macro href(f) -%}
    {%- if f.page and f.page.canonical_url -%}
        {{ f.page.canonical_url | e }}
    {%- elif f.url in ["", "./"] -%}
        {{ config.site_url }}
    {%- else -%}
        {{ config.site_url ~ f.url }}
    {%- endif -%}
{%- endmacro %}

{%- for locale, i18n_files in i18n_alternates.items() %}
{%- for file in i18n_files %}
    {%- if not file.page or file.page.is_link %}
        {%- continue %}
    {%- endif %}

        {{ href(file) }}
    {%- if file.page.meta and file.page.meta.git_revision_date_localized_raw_iso_date %}
        {{ file.page.meta.git_revision_date_localized_raw_iso_date }}
    {%- elif file.page.update_date %}
        {{ file.page.update_date }}
    {%- endif %}
    {%- if file.alternates | length > 1 %}
    {%- for i18n_locale, i18n_file in file.alternates.items() %}

    {%- endfor %}
    {%- if "en" in file.alternates %}

    {%- endif %}
    {%- endif %}

{%- endfor %}
{%- endfor %}
